ARRAY_WGT_HS_X_LEN         EQU 2   ; 2 elements
ARRAY_WGT_HS_Y_LEN         EQU 2   ; 2 elements
ARRAY_WGT_HS_W_LEN         EQU 2   ; 2 elements
ARRAY_WGT_HS_H_LEN         EQU 2   ; 2 elements
ARRAY_OPT_HS_X_LEN         EQU 2   ; 2 elements
ARRAY_OPT_HS_Y_LEN         EQU 2   ; 2 elements
ARRAY_OPT_HS_W_LEN         EQU 2   ; 2 elements
ARRAY_OPT_HS_H_LEN         EQU 2   ; 2 elements
ARRAY_CONS_HS_X_LEN         EQU 1   ; 1 elements
ARRAY_CONS_HS_Y_LEN         EQU 1   ; 1 elements
ARRAY_CONS_HS_W_LEN         EQU 1   ; 1 elements
ARRAY_CONS_HS_H_LEN         EQU 1   ; 1 elements
ARRAY_VAULT_HS_X_LEN         EQU 2   ; 2 elements
ARRAY_VAULT_HS_Y_LEN         EQU 2   ; 2 elements
ARRAY_VAULT_HS_W_LEN         EQU 2   ; 2 elements
ARRAY_VAULT_HS_H_LEN         EQU 2   ; 2 elements
ARRAY_NPC_STATE_LEN         EQU 4   ; 4 elements
ARRAY_INV_ITEMS_LEN         EQU 8   ; 8 elements

;***************************************************************************
; ARRAY DATA (ROM literals)
;***************************************************************************
; Arrays are stored in ROM and accessed via pointers
; At startup, main() initializes VAR_{name} to point to ARRAY_{name}_DATA

; Array literal for variable 'ITEM_WEIGHT' (8 elements, 2 bytes each)
MAIN:
    ; Initialize global variables
    CLR VPY_MOVE_X        ; MOVE offset defaults to 0
    CLR VPY_MOVE_Y        ; MOVE offset defaults to 0
    LDA #$F8
    STA TEXT_SCALE_H      ; Default height = -8 (normal size)
    LDA #$48
    STA TEXT_SCALE_W      ; Default width = 72 (normal size)
    LDD #0  ; const STATE_TITLE
    STD VAR_SCREEN
    LDD #0
    STD VAR_BLINK_TIMER
    LDD #0
    STD VAR_BLINK_ON
    LDD #0
    STD VAR_INTRO_PAGE
    LDD #0  ; const ROOM_ENTRANCE
    STD VAR_CURRENT_ROOM
    LDD #0
    STD VAR_PLAYER_X
    LDD #-115
    STD VAR_PLAYER_Y
    LDD #0
    STD VAR_SCROLL_X
    LDD #5
    STD VAR_PLAYER_SPEED
    LDD #0  ; const VERB_EXAMINE
    STD VAR_CURRENT_VERB
    LDD #-1
    STD VAR_NEAR_HS
    LDD #0
    STD VAR_MSG_ID
    LDD #0
    STD VAR_MSG_TIMER
    LDD #0
    STD VAR_ROOM_EXIT
    LDD #0
    STD VAR_FLAGS_A
    LDD #0
    STD VAR_FLAGS_B
    ; Copy array 'NPC_STATE' from ROM to RAM (4 elements)
    LDX #ARRAY_NPC_STATE_DATA       ; Source: ROM array data
    LDU #VAR_NPC_STATE_DATA       ; Dest: RAM array space
    LDD #4        ; Number of elements
.COPY_LOOP_0:
    LDY ,X++        ; Load word from ROM, increment source
    STY ,U++        ; Store word to RAM, increment dest
    SUBD #1         ; Decrement counter
    LBNE .COPY_LOOP_0 ; Loop until done (LBNE for long branch)
    LDX #VAR_NPC_STATE_DATA    ; Array now in RAM
    STX VAR_NPC_STATE
    LDD #1
    STD VAR_EXIT_ROOM_TARGET
    LDD #1  ; const MUSIC_TITLE
    STD VAR_CURRENT_MUSIC
    LDD #0
    STD VAR_BTN1_FIRED
    LDD #0
    STD VAR_BTN2_FIRED
    LDD #0
    STD VAR_BTN3_FIRED
    LDD #0
    STD VAR_PREV_BTN1
    LDD #0
    STD VAR_PREV_BTN2
    LDD #0
    STD VAR_PREV_BTN3
    ; Copy array 'INV_ITEMS' from ROM to RAM (8 elements)
    LDX #ARRAY_INV_ITEMS_DATA       ; Source: ROM array data
    LDU #VAR_INV_ITEMS_DATA       ; Dest: RAM array space
    LDD #8        ; Number of elements
.COPY_LOOP_1:
    LDY ,X++        ; Load word from ROM, increment source
    STY ,U++        ; Store word to RAM, increment dest
    SUBD #1         ; Decrement counter
    LBNE .COPY_LOOP_1 ; Loop until done (LBNE for long branch)
    LDX #VAR_INV_ITEMS_DATA    ; Array now in RAM
    STX VAR_INV_ITEMS
    LDD #0
    STD VAR_INV_COUNT
    LDD #0
    STD VAR_INV_WEIGHT
    LDD #0
    STD VAR_SHOW_INVENTORY
    LDD #-1
    STD VAR_ACTIVE_ITEM
    LDD #0
    STD VAR_INV_CURSOR
    LDD #60
    STD VAR_HEARTBEAT_TEMPO
    LDD #0
    STD VAR_HEARTBEAT_TIMER
    LDD #-110
    STD VAR_TESTAMENT_Y
    LDD #0
    STD VAR_TESTAMENT_PAGE
    LDD #-110
    STD VAR_ENDING_Y
    LDD #0
    STD VAR_SKIPPEDFRAMES
    ; === Initialize Joystick (one-time setup) ===
    JSR $F1AF    ; DP_to_C8 (required for RAM access)
    CLR $C823    ; CRITICAL: Clear analog mode flag (Joy_Analog does DEC on this)
    LDA #$01     ; CRITICAL: Resolution threshold (power of 2: $40=fast, $01=accurate)
    STA $C81A    ; Vec_Joy_Resltn (loop terminates when B=this value after LSRBs)
    LDA #$01
    STA $C81F    ; Vec_Joy_Mux_1_X (enable X axis reading)
    LDA #$03
    STA $C820    ; Vec_Joy_Mux_1_Y (enable Y axis reading)
    LDA #$00
    STA $C821    ; Vec_Joy_Mux_2_X (disable joystick 2 - CRITICAL!)
    STA $C822    ; Vec_Joy_Mux_2_Y (disable joystick 2 - saves cycles)
    ; Mux configured - J1_X()/J1_Y() can now be called

    ; Call main() for initialization
    ; PLAY_MUSIC("intro") - play music asset (index=1)
    LDX #1        ; Music asset index for lookup
    JSR PLAY_MUSIC_BANKED  ; Play with automatic bank switching
    LDD #0
    STD RESULT
    ; TODO: Statement Pass { source_line: 213 }

.MAIN_LOOP:
    JSR LOOP_BODY
    LBRA .MAIN_LOOP   ; Use long branch for multibank support

LOOP_BODY:
    JSR Wait_Recal   ; Synchronize with screen refresh (mandatory)
    JSR $F1BA    ; Read_Btns: PSG reg14 -> $C80F (active-HIGH), edge -> $C811
    LDD #10
    STD TMPVAL          ; Save right operand to TMPVAL (stack-safe temp)
    LDD >VAR_SKIPPEDFRAMES
    CMPD TMPVAL
    LBLT .CMP_0_TRUE
    LDD #0
    LBRA .CMP_0_END
.CMP_0_TRUE:
    LDD #1
.CMP_0_END:
    LBEQ IF_NEXT_1
    LDD >VAR_SKIPPEDFRAMES
    STD TMPVAL          ; Save left operand
    LDD #1
    ADDD TMPVAL         ; D = D + TMPVAL
    STD VAR_SKIPPEDFRAMES
    LDA >$C80F   ; Vec_Btns_1: bit0=1 means btn1 pressed
    BITA #$01
    LBNE .J1B1_0_ON
    LDD #0
    LBRA .J1B1_0_END
.J1B1_0_ON:
    LDD #1
.J1B1_0_END:
    STD RESULT
    STD VAR_PREV_BTN1
    LDA >$C80F   ; Vec_Btns_1: bit1=1 means btn2 pressed
    BITA #$02
    LBNE .J1B2_1_ON
    LDD #0
    LBRA .J1B2_1_END
.J1B2_1_ON:
    LDD #1
.J1B2_1_END:
    STD RESULT
    STD VAR_PREV_BTN2
    LDA >$C80F   ; Vec_Btns_1: bit2=1 means btn3 pressed
    BITA #$04
    LBNE .J1B3_2_ON
    LDD #0
    LBRA .J1B3_2_END
.J1B3_2_ON:
    LDD #1
.J1B3_2_END:
    STD RESULT
    STD VAR_PREV_BTN3
    RTS
    LBRA IF_END_0
IF_NEXT_1:
IF_END_0:
    LDA >$C80F   ; Vec_Btns_1: bit0=1 means btn1 pressed
    BITA #$01
    LBNE .J1B1_3_ON
    LDD #0
    LBRA .J1B1_3_END
.J1B1_3_ON:
    LDD #1
.J1B1_3_END:
    STD RESULT
    STD VAR_RAW1
    LDA >$C80F   ; Vec_Btns_1: bit1=1 means btn2 pressed
    BITA #$02
    LBNE .J1B2_4_ON
    LDD #0
    LBRA .J1B2_4_END
.J1B2_4_ON:
    LDD #1
.J1B2_4_END:
    STD RESULT
    STD VAR_RAW2
    LDA >$C80F   ; Vec_Btns_1: bit2=1 means btn3 pressed
    BITA #$04
    LBNE .J1B3_5_ON
    LDD #0
    LBRA .J1B3_5_END
.J1B3_5_ON:
    LDD #1
.J1B3_5_END:
    STD RESULT
    STD VAR_RAW3
    LDD #0
    STD VAR_BTN1_FIRED
    LDD #0
    STD VAR_BTN2_FIRED
    LDD #0
    STD VAR_BTN3_FIRED
    LDD #1
    STD TMPVAL          ; Save right operand to TMPVAL (stack-safe temp)
    LDD >VAR_RAW1
    CMPD TMPVAL
    LBEQ .CMP_2_TRUE
    LDD #0
    LBRA .CMP_2_END
.CMP_2_TRUE:
    LDD #1
.CMP_2_END:
    LBEQ .LOGIC_1_FALSE
    LDD #0
    STD TMPVAL          ; Save right operand to TMPVAL (stack-safe temp)
    LDD >VAR_PREV_BTN1
    CMPD TMPVAL
    LBEQ .CMP_3_TRUE
    LDD #0
    LBRA .CMP_3_END
.CMP_3_TRUE:
    LDD #1
.CMP_3_END:
    LBEQ .LOGIC_1_FALSE
    LDD #1
    LBRA .LOGIC_1_END
.LOGIC_1_FALSE:
    LDD #0
.LOGIC_1_END:
    LBEQ IF_NEXT_3
    LDD #1
    STD VAR_BTN1_FIRED
    LBRA IF_END_2
IF_NEXT_3:
IF_END_2:
    LDD #1
    STD TMPVAL          ; Save right operand to TMPVAL (stack-safe temp)
    LDD >VAR_RAW2
    CMPD TMPVAL
    LBEQ .CMP_5_TRUE
    LDD #0
    LBRA .CMP_5_END
.CMP_5_TRUE:
    LDD #1
.CMP_5_END:
    LBEQ .LOGIC_4_FALSE
    LDD #0
    STD TMPVAL          ; Save right operand to TMPVAL (stack-safe temp)
    LDD >VAR_PREV_BTN2
    CMPD TMPVAL
    LBEQ .CMP_6_TRUE
    LDD #0
    LBRA .CMP_6_END
.CMP_6_TRUE:
    LDD #1
.CMP_6_END:
    LBEQ .LOGIC_4_FALSE
    LDD #1
    LBRA .LOGIC_4_END
.LOGIC_4_FALSE:
    LDD #0
.LOGIC_4_END:
    LBEQ IF_NEXT_5
    LDD #1
    STD VAR_BTN2_FIRED
    LBRA IF_END_4
IF_NEXT_5:
IF_END_4:
    LDD #1
    STD TMPVAL          ; Save right operand to TMPVAL (stack-safe temp)
    LDD >VAR_RAW3
    CMPD TMPVAL
    LBEQ .CMP_8_TRUE
    LDD #0
    LBRA .CMP_8_END
.CMP_8_TRUE:
    LDD #1
.CMP_8_END:
    LBEQ .LOGIC_7_FALSE
    LDD #0
    STD TMPVAL          ; Save right operand to TMPVAL (stack-safe temp)
    LDD >VAR_PREV_BTN3
    CMPD TMPVAL
    LBEQ .CMP_9_TRUE
    LDD #0
    LBRA .CMP_9_END
.CMP_9_TRUE:
    LDD #1
.CMP_9_END:
    LBEQ .LOGIC_7_FALSE
    LDD #1
    LBRA .LOGIC_7_END
.LOGIC_7_FALSE:
    LDD #0
.LOGIC_7_END:
    LBEQ IF_NEXT_7
    LDD #1
    STD VAR_BTN3_FIRED
    LBRA IF_END_6
IF_NEXT_7:
IF_END_6:
    LDD >VAR_RAW1
    STD VAR_PREV_BTN1
    LDD >VAR_RAW2
    STD VAR_PREV_BTN2
    LDD >VAR_RAW3
    STD VAR_PREV_BTN3
    LDD #2  ; const STATE_ROOM
    STD TMPVAL          ; Save right operand to TMPVAL (stack-safe temp)
    LDD >VAR_SCREEN
    CMPD TMPVAL
    LBEQ .CMP_10_TRUE
    LDD #0
    LBRA .CMP_10_END
.CMP_10_TRUE:
    LDD #1
.CMP_10_END:
    LBEQ IF_NEXT_9
    LDD >VAR_HEARTBEAT_TIMER
    STD TMPVAL          ; Save left operand to TMPVAL (stack-safe temp)
    LDD #1
    ADDD TMPVAL         ; D = D + LEFT (from TMPVAL)
    STD VAR_HEARTBEAT_TIMER
    LDD >VAR_HEARTBEAT_TEMPO
    STD TMPVAL          ; Save right operand to TMPVAL (stack-safe temp)
    LDD >VAR_HEARTBEAT_TIMER
    CMPD TMPVAL
    LBGE .CMP_11_TRUE
    LDD #0
    LBRA .CMP_11_END
.CMP_11_TRUE:
    LDD #1
.CMP_11_END:
    LBEQ IF_NEXT_11
    LDD #0
    STD VAR_HEARTBEAT_TIMER
    ; PLAY_SFX("heartbeat") - play SFX asset (index=1)
    LDX #1        ; SFX asset index for lookup
    JSR PLAY_SFX_BANKED  ; Play with automatic bank switching
    LDD #0
    STD RESULT
    LBRA IF_END_10
IF_NEXT_11:
IF_END_10:
    LBRA IF_END_8
IF_NEXT_9:
IF_END_8:
    LDD #1
    STD TMPVAL          ; Save right operand to TMPVAL (stack-safe temp)
    LDD >VAR_BTN2_FIRED
    CMPD TMPVAL
    LBEQ .CMP_12_TRUE
    LDD #0
    LBRA .CMP_12_END
.CMP_12_TRUE:
    LDD #1
.CMP_12_END:
    LBEQ IF_NEXT_13
    LDD #2  ; const STATE_ROOM
    STD TMPVAL          ; Save right operand to TMPVAL (stack-safe temp)
    LDD >VAR_SCREEN
    CMPD TMPVAL
    LBEQ .CMP_13_TRUE
    LDD #0
    LBRA .CMP_13_END
.CMP_13_TRUE:
    LDD #1
.CMP_13_END:
    LBEQ IF_NEXT_15
    LDD #0
    STD TMPVAL          ; Save right operand to TMPVAL (stack-safe temp)
    LDD >VAR_SHOW_INVENTORY
    CMPD TMPVAL
    LBEQ .CMP_14_TRUE
    LDD #0
    LBRA .CMP_14_END
.CMP_14_TRUE:
    LDD #1
.CMP_14_END:
    LBEQ IF_NEXT_17
    LDD #1
    STD VAR_SHOW_INVENTORY
    LBRA IF_END_16
IF_NEXT_17:
    LDD #0
    STD VAR_SHOW_INVENTORY
IF_END_16:
    LBRA IF_END_14
IF_NEXT_15:
IF_END_14:
    LBRA IF_END_12
IF_NEXT_13:
IF_END_12:
    LDD #0  ; const STATE_TITLE
    STD TMPVAL          ; Save right operand to TMPVAL (stack-safe temp)
    LDD >VAR_SCREEN
    CMPD TMPVAL
    LBEQ .CMP_15_TRUE
    LDD #0
    LBRA .CMP_15_END
.CMP_15_TRUE:
    LDD #1
.CMP_15_END:
    LBEQ IF_NEXT_19
    JSR TRAMP_DRAW_TITLE  ; cross-bank trampoline (bank #0 -> bank #1)
    LBRA IF_END_18
IF_NEXT_19:
    LDD #1  ; const STATE_INTRO
    STD TMPVAL          ; Save right operand to TMPVAL (stack-safe temp)
    LDD >VAR_SCREEN
    CMPD TMPVAL
    LBEQ .CMP_16_TRUE
