.CMP_16_TRUE:
    LDD #1
.CMP_16_END:
    LBEQ IF_NEXT_20
    JSR TRAMP_DRAW_INTRO  ; cross-bank trampoline (bank #0 -> bank #1)
    LBRA IF_END_18
IF_NEXT_20:
    LDD #2  ; const STATE_ROOM
    STD TMPVAL          ; Save right operand to TMPVAL (stack-safe temp)
    LDD >VAR_SCREEN
    CMPD TMPVAL
    LBEQ .CMP_17_TRUE
