    LBRA .CMP_17_END
.CMP_17_TRUE:
    LDD #1
.CMP_17_END:
    LBEQ IF_NEXT_21
    JSR UPDATE_ROOM
    LDD #1
    STD TMPVAL          ; Save right operand to TMPVAL (stack-safe temp)
    LDD >VAR_SHOW_INVENTORY
    CMPD TMPVAL
    LBEQ .CMP_18_TRUE
