.CMP_18_END:
    LBEQ IF_NEXT_23
    JSR TRAMP_DRAW_INVENTORY  ; cross-bank trampoline (bank #0 -> bank #1)
    LBRA IF_END_22
IF_NEXT_23:
    JSR TRAMP_DRAW_ROOM  ; cross-bank trampoline (bank #0 -> bank #1)
IF_END_22:
    LBRA IF_END_18
IF_NEXT_21:
    LDD #4  ; const STATE_TESTAMENT
    STD TMPVAL          ; Save right operand to TMPVAL (stack-safe temp)
    LDD >VAR_SCREEN
    CMPD TMPVAL
    LBEQ .CMP_19_TRUE
