    LBRA .CMP_20_END
.CMP_20_TRUE:
    LDD #1
.CMP_20_END:
    LBEQ IF_END_18
    JSR DRAW_ENDING
    LBRA IF_END_18
IF_END_18:
    JSR AUDIO_UPDATE  ; Auto-injected: update music + SFX (after all game logic)
    RTS

; Function: ENTER_ROOM (Bank #0)
ENTER_ROOM:
    LDD >VAR_ARG0
    STD VAR_CURRENT_ROOM
    LDD #-1
    STD VAR_NEAR_HS
    LDD #0
    STD VAR_MSG_ID
    LDD #0
    STD VAR_MSG_TIMER
    LDD #0
    STD VAR_ROOM_EXIT
    LDD #0
    STD VAR_SHOW_INVENTORY
    LDD #0  ; const ROOM_ENTRANCE
    STD TMPVAL          ; Save right operand to TMPVAL (stack-safe temp)
    LDD >VAR_ARG0
    CMPD TMPVAL
    LBEQ .CMP_29_TRUE
    LDD #0
    LBRA .CMP_29_END
.CMP_29_TRUE:
    LDD #1
.CMP_29_END:
    LBEQ IF_NEXT_40
    ; ===== LOAD_LEVEL builtin =====
    ; Load level: 'entrance'
    ; Level asset index: 3 (multibank)
    LDX #3
    JSR LOAD_LEVEL_BANKED
    LDD #0
    STD VAR_PLAYER_X
    LDD #-115
    STD VAR_PLAYER_Y
    LDD #0
    STD VAR_SCROLL_X
    ; ===== SET_CAMERA_X builtin =====
    LDD #0
    STD >CAMERA_X    ; Store 16-bit camera X scroll offset
    LDD #0
    STD RESULT
    LDD #2  ; const MUSIC_EXPLORATION
    STD TMPVAL          ; Save right operand to TMPVAL (stack-safe temp)
    LDD >VAR_CURRENT_MUSIC
    CMPD TMPVAL
    LBNE .CMP_30_TRUE
    LDD #0
    LBRA .CMP_30_END
.CMP_30_TRUE:
    LDD #1
.CMP_30_END:
    LBEQ IF_NEXT_42
    ; PLAY_MUSIC("exploration") - play music asset (index=0)
    LDX #0        ; Music asset index for lookup
    JSR PLAY_MUSIC_BANKED  ; Play with automatic bank switching
    LDD #0
    STD RESULT
    LDD #2  ; const MUSIC_EXPLORATION
    STD VAR_CURRENT_MUSIC
